  const win=el.querySelector('.op-window'),toolbar=el.querySelector('.op-toolbar'),body=el.querySelector('.op-grid tbody');if(win)win.classList.add('type-size-window');if(toolbar)toolbar.insertAdjacentHTML('afterbegin','<div class="op-search"><span>⌕</span><input id="typeSizeSearch" placeholder="Pesquisar aqui..."></div>');const search=document.getElementById('typeSizeSearch');if(search)search.oninput=e=>{const q=e.target.value.toLowerCase();body.querySelectorAll('tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none');};
