let typeSizeOptionsOpen=false;
function toggleTypeSizeOptions(){typeSizeOptionsOpen=!typeSizeOptionsOpen;renderTypesSizes(document.getElementById('view-complementos'));}
function exportTypesSizesCsv(){typeSizeOptionsOpen=false;const types=state.complementos.filter(x=>x.recordKind==='type'),sizes=state.complementos.filter(x=>x.recordKind==='size');downloadCsvFile('tipos-e-tamanhos-'+todayStr()+'.csv',[['Tipo','Sigla Tipo','Tamanho','Sigla Tamanho','Preço adicional','Situação'],...sizes.map(s=>{const t=types.find(x=>x.id===s.parentId)||{};return[t.nome||'',t.code||'',s.nome||'',s.code||'',s.preco||0,s.active===false?'pausado':'ativo'];}),...types.filter(t=>!sizes.some(s=>s.parentId===t.id)).map(t=>[t.nome,t.code||'','','','',t.active===false?'pausado':'ativo'])]);}
function exportTypesSizesPackage(){typeSizeOptionsOpen=false;downloadJsonFile('pacote-tipos-tamanhos-'+todayStr()+'.json',{format:'cantina-tipos-tamanhos',version:1,exportedAt:new Date().toISOString(),records:state.complementos.filter(x=>x.recordKind==='type'||x.recordKind==='size')});}
function duplicateSelectedTypeSize(){typeSizeOptionsOpen=false;const source=state.complementos.find(x=>x.id===selectedTypeSizeId&&(x.recordKind==='type'||x.recordKind==='size'));if(!source){toast('Selecione um tipo ou tamanho para duplicar.');return;}const copy={...JSON.parse(JSON.stringify(source)),id:uid(),code:'',nome:source.nome+' — Cópia'};state.complementos.push(copy);selectedTypeSizeId=copy.id;save('complementos');renderAll();toast('Registro duplicado para revisão.');}
function importTypesSizesPackage(){typeSizeOptionsOpen=false;const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const data=JSON.parse(await input.files[0].text()),records=Array.isArray(data)?data:data&&data.format==='cantina-tipos-tamanhos'?data.records:null;if(!Array.isArray(records)||!records.length)throw new Error('Pacote de tipos e tamanhos inválido.');if(!confirm(`Importar ${records.length} registro(s)?`))return;const idMap=new Map();let added=0,updated=0;records.filter(x=>x.recordKind==='type').forEach(raw=>{const existing=state.complementos.find(x=>x.recordKind==='type'&&((raw.id&&x.id===raw.id)||(raw.code&&x.code===raw.code)||String(x.nome).toLowerCase()===String(raw.nome).toLowerCase())),target=existing||{id:uid()};idMap.set(raw.id,target.id);Object.assign(target,{recordKind:'type',nome:String(raw.nome||'').trim(),code:String(raw.code||'').trim(),preco:0,parentId:null,active:raw.active!==false});if(existing)updated++;else{state.complementos.push(target);added++;}});records.filter(x=>x.recordKind==='size').forEach(raw=>{const parentId=idMap.get(raw.parentId)||raw.parentId;if(!state.complementos.some(x=>x.id===parentId&&x.recordKind==='type'))return;const existing=state.complementos.find(x=>x.recordKind==='size'&&((raw.id&&x.id===raw.id)||(raw.code&&x.code===raw.code&&x.parentId===parentId))),target=existing||{id:uid()};idMap.set(raw.id,target.id);Object.assign(target,{recordKind:'size',nome:String(raw.nome||'').trim(),code:String(raw.code||'').trim(),preco:Math.max(0,Number(raw.preco)||0),parentId,active:raw.active!==false});if(existing)updated++;else{state.complementos.push(target);added++;}});save('complementos');renderAll();toast(`${added} registro(s) incluído(s) e ${updated} atualizado(s).`);}catch(error){toast(error.message||'Não foi possível importar o pacote.');}};input.click();}
const renderTypesSizesBase=renderTypesSizes;
renderTypesSizes=function(el){renderTypesSizesBase(el);const toolbar=el.querySelector('.op-toolbar'),spacer=toolbar&&toolbar.querySelector('.op-toolbar-spacer');if(!toolbar||!spacer)return;const wrap=document.createElement('div');wrap.className='pdv-menu-wrap';wrap.innerHTML=`<button class="op-btn" onclick="toggleTypeSizeOptions()">••• &nbsp; Opções ▾</button>${typeSizeOptionsOpen?`<div class="pdv-menu" style="top:48px;right:0;left:auto;min-width:260px"><button onclick="typeSizeOptionsOpen=false;window.print()">▣ Imprimir</button><button onclick="typeSizeOptionsOpen=false;renderAll();toast('Lista atualizada.')">↻ Atualizar</button><button onclick="duplicateSelectedTypeSize()" ${selectedTypeSizeId?'':'disabled'}>▣ Duplicar selecionado</button><b>Exportar Tipos e Tamanhos</b><button onclick="exportTypesSizesCsv()">▧ Para arquivo CSV</button><button onclick="exportTypesSizesPackage()">▧ Pacote completo</button><b>Importar Tipos e Tamanhos</b><button onclick="importTypesSizesPackage()">▧ De pacote completo</button></div>`:''}`;spacer.insertAdjacentElement('afterend',wrap);};
function selectCrudRow(entityKey,id){crudSelected[entityKey]=id;renderCrudView('view-'+({paymentMethods:'pagamentos',contaCategorias:'contascategorias'}[entityKey]||entityKey),entityKey);}
function editSelectedCrud(entityKey){if(!crudSelected[entityKey]){toast('Selecione um registro para editar.');return;}openCrudModal(entityKey,crudSelected[entityKey]);}
