function openCrudOrdering(entityKey){crudOptions[entityKey]=false;const cfg=CRUD_CONFIGS[entityKey],list=state[entityKey]||[];if(!list.length){toast('Não há registros para ordenar.');return;}window.crudOrderDraft=list.map(x=>x.id);openModal('Ordenação Manual — '+cfg.title,`<p class="sub">Use as setas para definir a sequência exibida na lista.</p><div id="crudOrderList" class="finance-grid" style="height:390px"></div><div class="consumer-modal-actions"><button onclick="closeModal()">Voltar</button><button class="consumer-save" onclick="saveCrudOrdering(${jsArg(entityKey)})">✓ Salvar ordem</button></div>`,true);renderCrudOrdering(entityKey);}
function renderCrudOrdering(entityKey){const cfg=CRUD_CONFIGS[entityKey],el=document.getElementById('crudOrderList');if(!el)return;el.innerHTML=`<table><thead><tr><th>Posição</th><th>${h(cfg.fields[0].label)}</th><th>Movimentar</th></tr></thead><tbody>${window.crudOrderDraft.map((id,index)=>{const item=state[entityKey].find(x=>x.id===id);return `<tr><td>${index+1}</td><td>${h(item&&item[cfg.fields[0].key]||'—')}</td><td><button class="op-mini" onclick="moveCrudOrder(${jsArg(entityKey)},${index},-1)" ${index===0?'disabled':''}>↑</button><button class="op-mini" onclick="moveCrudOrder(${jsArg(entityKey)},${index},1)" ${index===window.crudOrderDraft.length-1?'disabled':''}>↓</button></td></tr>`}).join('')}</tbody></table>`;}
function moveCrudOrder(entityKey,index,delta){const next=index+delta;if(next<0||next>=window.crudOrderDraft.length)return;[window.crudOrderDraft[index],window.crudOrderDraft[next]]=[window.crudOrderDraft[next],window.crudOrderDraft[index]];renderCrudOrdering(entityKey);}
function saveCrudOrdering(entityKey){const map=new Map(state[entityKey].map(x=>[x.id,x]));state[entityKey]=window.crudOrderDraft.map(id=>map.get(id)).filter(Boolean);state[entityKey].forEach((x,i)=>x.sortOrder=i);save(entityKey);closeModal();renderAll();toast('Ordenação salva.');}
if(typeof document.addEventListener==='function')document.addEventListener('click',event=>{const button=event.target.closest&&event.target.closest('.pdv-menu button');if(!button||!button.textContent.includes('Ordenação manual'))return;const view=button.closest('.view'),map={categorias:'categorias',observacoes:'observacoes',perguntas:'perguntas',complementos:'complementos'},entity=map[(view&&view.id||'').replace('view-','')];if(!entity)return;event.preventDefault();event.stopImmediatePropagation();openCrudOrdering(entity);},true);
function observationLinkedProducts(item){const direct=Array.isArray(item&&item.productIds)?item.productIds:[],legacy=state.products.filter(p=>(p.observationIds||[]).includes(item&&item.id)).map(p=>p.id);return[...new Set([...direct,...legacy])];}
function exportObservationsCsv(){crudOptions.observacoes=false;downloadCsvFile('observacoes-'+todayStr()+'.csv',[['Código','Observação','Código PDV','Situação','Produtos vinculados'],...state.observacoes.map((x,i)=>[x.code||i+1,x.texto,x.pdvCode||'',x.active===false?'pausada':'ativa',observationLinkedProducts(x).map(id=>(state.products.find(p=>p.id===id)||{}).name).filter(Boolean).join('|')])]);}
