function duplicateSelectedObservation(){crudOptions.observacoes=false;const source=state.observacoes.find(x=>x.id===crudSelected.observacoes);if(!source){toast('Selecione uma observação para duplicar.');return;}const copy={...JSON.parse(JSON.stringify(source)),id:uid(),code:'',pdvCode:'',texto:source.texto+' — Cópia',sortOrder:state.observacoes.length};state.observacoes.push(copy);crudSelected.observacoes=copy.id;save('observacoes');renderAll();toast('Observação duplicada para revisão.');}
function setObservationsStatus(active){crudOptions.observacoes=false;const selected=crudSelected.observacoes?[crudSelected.observacoes]:state.observacoes.map(x=>x.id);selected.forEach(id=>{const item=state.observacoes.find(x=>x.id===id);if(item)item.active=active;});save('observacoes');renderAll();toast(`${selected.length} observação(ões) ${active?'ativada(s)':'pausada(s)'}.`);}
function importObservationsFile(format='csv'){crudOptions.observacoes=false;const input=document.createElement('input');input.type='file';input.accept=format==='json'?'.json,application/json':'.csv,text/csv';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{let incoming;if(format==='json'){const data=JSON.parse(await file.text());incoming=Array.isArray(data)?data:data&&data.format==='cantina-observacoes'?data.observations:null;if(!Array.isArray(incoming))throw new Error('Pacote de observações inválido.');}else{const lines=(await file.text()).replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);incoming=lines.slice(1).map(line=>{const c=line.split(';').map(v=>v.replace(/^"|"$/g,'').replace(/""/g,'"'));return{code:(c[0]||'').trim(),texto:(c[1]||'').trim(),pdvCode:(c[2]||'').trim(),active:String(c[3]||'ativa').toLowerCase()!=='pausada',productNames:(c[4]||'').split('|').map(x=>x.trim()).filter(Boolean)};}).filter(x=>x.texto);}if(!incoming.length)throw new Error('Nenhuma observação válida foi encontrada.');if(!confirm(`Importar ${incoming.length} observação(ões) de ${file.name}?`))return;let added=0,updated=0;incoming.forEach(raw=>{const code=String(raw.code||'').trim(),existing=state.observacoes.find(x=>(raw.id&&x.id===raw.id)||(code&&x.code===code));const productIds=Array.isArray(raw.productIds)?raw.productIds.filter(id=>state.products.some(p=>p.id===id)):(raw.productNames||[]).map(name=>(state.products.find(p=>String(p.name).toLowerCase()===String(name).toLowerCase())||{}).id).filter(Boolean);const target=existing||{id:raw.id||uid()};Object.assign(target,{code,texto:String(raw.texto||'').trim(),pdvCode:String(raw.pdvCode||''),active:raw.active!==false,productIds,sortOrder:Number(raw.sortOrder)||state.observacoes.length});if(existing)updated++;else{state.observacoes.push(target);added++;}state.products.forEach(p=>{p.observationIds=(p.observationIds||[]).filter(id=>id!==target.id);if(productIds.includes(p.id))p.observationIds.push(target.id);});});save('observacoes');save('products');renderAll();toast(`${added} observação(ões) incluída(s) e ${updated} atualizada(s).`);}catch(error){toast(error.message||'Não foi possível importar o arquivo.');}};input.click();}
function renderObservations(el){const list=(state.observacoes||[]).slice().sort((a,b)=>(Number(a.sortOrder)||0)-(Number(b.sortOrder)||0)),rows=list.map((item,index)=>`<tr data-search="${h(String(item.texto||'').toLowerCase())}" class="${crudSelected.observacoes===item.id?'selected':''}" onclick="crudSelected.observacoes=${jsArg(item.id)};renderObservations(document.getElementById('view-observacoes'))" ondblclick="openObservationModal(${jsArg(item.id)})"><td>${h(item.code||String(index+1).padStart(3,'0'))}</td><td>${h(item.texto||'—')}</td><td>${observationLinkedProducts(item).length}</td><td>${item.active===false?'Pausada':'À venda'}</td><td>${h(item.pdvCode||'—')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Não há observações cadastradas</td></tr>';el.innerHTML=`<div class="workspace-gray"><section class="op-window observation-window"><header class="op-titlebar"><span>Observações</span><span class="op-controls"><span onclick="closeOperationalWindow()" style="cursor:pointer" title="Fechar">×</span></span></header><div class="op-toolbar"><div class="op-search"><span>⌕</span><input id="observationSearch" placeholder="Pesquisar aqui..."></div><div class="op-toolbar-spacer"></div><div class="pdv-menu-wrap"><button class="op-btn" onclick="toggleCrudOptions('observacoes')">••• &nbsp; Opções ▾</button>${crudOptions.observacoes?`<div class="pdv-menu" style="top:48px;right:0;left:auto;min-width:270px"><button onclick="crudOptions.observacoes=false;window.print()">▣ Imprimir</button><button onclick="openCrudOrdering('observacoes')">↕ Ordenação manual</button><button onclick="crudOptions.observacoes=false;renderAll();toast('Lista atualizada.')">↻ Atualizar</button><button onclick="duplicateSelectedObservation()" ${crudSelected.observacoes?'':'disabled'}>▣ Duplicar selecionada</button><b>Alterar Situação</b><button onclick="setObservationsStatus(true)">✓ Ativar ${crudSelected.observacoes?'selecionada':'todas'}</button><button onclick="setObservationsStatus(false)">‖ Pausar ${crudSelected.observacoes?'selecionada':'todas'}</button><b>Exportar Observações</b><button onclick="exportObservationsCsv()">▧ Para arquivo CSV</button><button onclick="exportObservationsPackage()">▧ Pacote completo</button><b>Importar Observações</b><button onclick="importObservationsFile('csv')">▧ De arquivo CSV</button><button onclick="importObservationsFile('json')">▧ De pacote completo</button></div>`:''}</div><button class="op-btn" onclick="editSelectedCrud('observacoes')" ${crudSelected.observacoes?'':'disabled'}>✎ &nbsp; Editar</button><button class="op-btn primary" onclick="openObservationModal()">＋ &nbsp; Novo</button></div><div class="op-tabs"><button class="active">Observações (${list.length})</button></div><div class="op-grid"><table><thead><tr><th>Cód. Sistema</th><th>Observação</th><th>Qtd. Produtos Vinculados</th><th>Status Venda</th><th>Cód. PDV</th></tr></thead><tbody id="observationRows">${rows}</tbody></table></div><footer class="op-footer"><span>Registros: ${list.length}</span><span>Ordenação: Manual</span></footer></section></div>`;document.getElementById('observationSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#observationRows tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none');};}
function openObservationModal(id){const item=id?state.observacoes.find(x=>x.id===id):null,linked=new Set(observationLinkedProducts(item)),checks=state.products.map(p=>`<label style="display:flex;gap:8px;padding:7px 10px;border-bottom:1px solid var(--c-border)"><input class="obs-product" type="checkbox" value="${p.id}" ${linked.has(p.id)?'checked':''}> ${h(p.name)}</label>`).join('');openModal(item?'Editar Observação':'Nova Observação',`<div class="record-body"><div class="record-tabs"><button class="active">Principal</button></div><div class="consumer-form-frame" style="min-height:360px"><div class="comp-code-row"><span>Código do sistema:</span><b>${h(item&&item.code||'')}</b><label class="comp-switch"><input id="obsActive" type="checkbox" ${!item||item.active!==false?'checked':''}><span></span> Ativa</label></div><div class="field"><label>Observação</label><input id="obsText" maxlength="150" value="${h(item&&item.texto||'')}" autofocus></div><div class="field"><label>Produtos Vinculados</label><div class="comp-product-picker" style="position:static;display:block;max-height:210px">${checks||'<p class="empty">Nenhum produto cadastrado.</p>'}</div></div><div class="field"><label>Código PDV</label><input id="obsPdv" value="${h(item&&item.pdvCode||'')}"></div></div><div class="consumer-modal-actions"><button class="consumer-delete" id="obsDelete" ${item?'':'disabled'}>✕ Excluir</button><span style="flex:1"></span><button onclick="closeModal()">〈 Voltar</button><button class="consumer-save" id="obsSave">✓ Salvar</button></div></div>`);document.querySelector('#modalRoot .modal').classList.add('record-modal');document.getElementById('obsSave').onclick=()=>{const texto=document.getElementById('obsText').value.trim();if(!texto){toast('Informe a observação.');return;}const productIds=[...document.querySelectorAll('.obs-product:checked')].map(x=>x.value),target=item||{id:uid(),code:String(state.observacoes.length+1).padStart(3,'0')};Object.assign(target,{texto,productIds,pdvCode:document.getElementById('obsPdv').value.trim(),active:document.getElementById('obsActive').checked});if(!item)state.observacoes.push(target);state.products.forEach(p=>{p.observationIds=(p.observationIds||[]).filter(x=>x!==target.id);if(productIds.includes(p.id))p.observationIds.push(target.id);});save('observacoes');save('products');closeModal();renderAll();toast('Observação salva.');};if(item)document.getElementById('obsDelete').onclick=()=>deleteCrudItem('observacoes',item.id);}
function categoryProductCount(category){return state.products.filter(p=>p.categoryId===category.id||(!p.categoryId&&p.category===category.nome)).length;}
function exportCategoriesCsv(){crudOptions.categorias=false;downloadCsvFile('categorias-'+todayStr()+'.csv',[['Código','Categoria','Categoria Principal','Código PDV','Cor','Situação'],...state.categorias.map((x,i)=>[x.code||i+1,x.nome,(state.categorias.find(p=>p.id===x.parentId)||{}).nome||'',x.pdvCode||'',x.color||'',x.active===false?'pausada':'ativa'])]);}
