function duplicateSelectedCategory(){crudOptions.categorias=false;const source=state.categorias.find(x=>x.id===crudSelected.categorias);if(!source){toast('Selecione uma categoria para duplicar.');return;}const copy={...source,id:uid(),code:'',pdvCode:'',nome:source.nome+' — Cópia',parentId:source.parentId||null,sortOrder:state.categorias.length};state.categorias.push(copy);crudSelected.categorias=copy.id;save('categorias');renderAll();toast('Categoria duplicada para revisão.');}
function importCategoriesFile(format='csv'){crudOptions.categorias=false;const input=document.createElement('input');input.type='file';input.accept=format==='json'?'.json,application/json':'.csv,text/csv';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{let incoming;if(format==='json'){const data=JSON.parse(await file.text());incoming=Array.isArray(data)?data:data&&data.format==='cantina-categorias'?data.categories:null;if(!Array.isArray(incoming))throw new Error('Pacote de categorias inválido.');}else{const lines=(await file.text()).replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);incoming=lines.slice(1).map(line=>{const c=line.split(';').map(v=>v.replace(/^"|"$/g,'').replace(/""/g,'"'));return{code:(c[0]||'').trim(),nome:(c[1]||'').trim(),parentName:(c[2]||'').trim(),pdvCode:(c[3]||'').trim(),color:(c[4]||'').trim(),active:String(c[5]||'ativa').toLowerCase()!=='pausada'};}).filter(x=>x.nome);}if(!incoming.length)throw new Error('Nenhuma categoria válida foi encontrada.');if(!confirm(`Importar ${incoming.length} categoria(s) de ${file.name}?`))return;let added=0,updated=0;incoming.forEach(raw=>{const code=String(raw.code||'').trim(),existing=state.categorias.find(x=>(raw.id&&x.id===raw.id)||(code&&x.code===code)||String(x.nome).toLowerCase()===String(raw.nome).toLowerCase());const target=existing||{id:raw.id||uid()};Object.assign(target,{code,nome:String(raw.nome).trim(),pdvCode:String(raw.pdvCode||''),color:/^#[0-9a-f]{6}$/i.test(raw.color||'')?raw.color:'#3568b0',active:raw.active!==false,sortOrder:Number(raw.sortOrder)||state.categorias.length});target._importParentId=raw.parentId||null;target._importParentName=raw.parentName||'';if(existing)updated++;else{state.categorias.push(target);added++;}});state.categorias.forEach(x=>{if(x._importParentId||x._importParentName){const parent=state.categorias.find(p=>p.id===x._importParentId||String(p.nome).toLowerCase()===String(x._importParentName).toLowerCase());x.parentId=parent&&parent.id!==x.id?parent.id:null;}delete x._importParentId;delete x._importParentName;});save('categorias');renderAll();toast(`${added} categoria(s) incluída(s) e ${updated} atualizada(s).`);}catch(error){toast(error.message||'Não foi possível importar o arquivo.');}};input.click();}
function renderCategories(el){const list=(state.categorias||[]).slice().sort((a,b)=>(Number(a.sortOrder)||0)-(Number(b.sortOrder)||0)||String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR')),rows=list.map((item,index)=>{const parent=state.categorias.find(x=>x.id===item.parentId);return `<tr data-search="${h(((item.nome||'')+' '+(parent&&parent.nome||'')).toLowerCase())}" class="${crudSelected.categorias===item.id?'selected':''}" onclick="crudSelected.categorias=${jsArg(item.id)};renderCategories(document.getElementById('view-categorias'))" ondblclick="openCategoryModal(${jsArg(item.id)})"><td>${h(item.code||String(index+1).padStart(3,'0'))}</td><td>${parent?'↳ ':''}${h(item.nome||'—')}</td><td>${h(parent&&parent.nome||'—')}</td><td>${categoryProductCount(item)}</td><td><span class="tag ${item.active===false?'tag-gray':'tag-green'}">${item.active===false?'Pausada':'À venda'}</span></td><td>${h(item.pdvCode||'—')}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Não há categorias cadastradas</td></tr>';el.innerHTML=`<div class="workspace-gray"><section class="op-window category-window"><header class="op-titlebar"><span>Categorias</span><span class="op-controls"><span onclick="closeOperationalWindow()" style="cursor:pointer" title="Fechar">×</span></span></header><div class="op-toolbar"><div class="op-search"><span>⌕</span><input id="categorySearch" placeholder="Pesquisar aqui..."></div><div class="op-toolbar-spacer"></div><div class="pdv-menu-wrap"><button class="op-btn" onclick="toggleCrudOptions('categorias')">••• &nbsp; Opções ▾</button>${crudOptions.categorias?`<div class="pdv-menu" style="top:48px;right:0;left:auto;min-width:260px"><button onclick="crudOptions.categorias=false;window.print()">▣ Imprimir</button><button onclick="openCrudOrdering('categorias')">↕ Ordenação manual</button><button onclick="crudOptions.categorias=false;renderAll();toast('Lista atualizada.')">↻ Atualizar</button><button onclick="duplicateSelectedCategory()" ${crudSelected.categorias?'':'disabled'}>▣ Duplicar selecionada</button><b>Exportar Categorias</b><button onclick="exportCategoriesCsv()">▧ Para arquivo CSV</button><button onclick="exportCategoriesPackage()">▧ Pacote completo</button><b>Importar Categorias</b><button onclick="importCategoriesFile('csv')">▧ De arquivo CSV</button><button onclick="importCategoriesFile('json')">▧ De pacote completo</button></div>`:''}</div><button class="op-btn" onclick="editSelectedCrud('categorias')" ${crudSelected.categorias?'':'disabled'}>✎ &nbsp; Editar</button><button class="op-btn primary" onclick="openCategoryModal()">＋ &nbsp; Novo</button></div><div class="op-tabs"><button class="active">Categorias (${list.length})</button></div><div class="op-grid"><table><thead><tr><th>Cód. Sistema</th><th>Categoria</th><th>Categoria Principal</th><th>Produtos Vinculados</th><th>Status Venda</th><th>Cód. PDV</th></tr></thead><tbody id="categoryRows">${rows}</tbody></table></div><footer class="op-footer"><span>Registros: ${list.length}</span><span>Ordenação: Manual</span></footer></section></div>`;document.getElementById('categorySearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#categoryRows tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none');};}
function openCategoryModal(id){const item=id?state.categorias.find(x=>x.id===id):null,parents=state.categorias.filter(x=>x.id!==id&&!x.parentId);openModal(item?'Editar Categoria':'Nova Categoria',`<div class="record-body"><div class="record-tabs"><button class="active">Principal</button></div><div class="consumer-form-frame" style="min-height:310px"><div class="comp-code-row"><span>Código do sistema:</span><b>${h(item&&item.code||'')}</b><label class="comp-switch"><input id="categoryActive" type="checkbox" ${!item||item.active!==false?'checked':''}><span></span> Ativa</label></div><div class="field"><label>Nome</label><input id="categoryName" maxlength="100" value="${h(item&&item.nome||'')}" autofocus></div><div class="field"><label>Subcategoria de</label><select id="categoryParent"><option value="">Categoria principal</option>${parents.map(p=>`<option value="${p.id}" ${item&&item.parentId===p.id?'selected':''}>${h(p.nome)}</option>`).join('')}</select></div><div class="row"><div class="field"><label>Código PDV</label><input id="categoryPdv" value="${h(item&&item.pdvCode||'')}"></div><div class="field"><label>Cor de identificação</label><input id="categoryColor" type="color" value="${h(item&&item.color||'#3568b0')}"></div></div></div><div class="consumer-modal-actions"><button class="consumer-delete" id="categoryDelete" ${item?'':'disabled'}>✕ Excluir</button><span style="flex:1"></span><button onclick="closeModal()">〈 Voltar</button><button class="consumer-save" id="categorySave">✓ Salvar</button></div></div>`);document.querySelector('#modalRoot .modal').classList.add('record-modal');document.getElementById('categorySave').onclick=()=>{const nome=document.getElementById('categoryName').value.trim();if(!nome){toast('Informe o nome da categoria.');return;}if(state.categorias.some(x=>x.id!==id&&String(x.nome).toLowerCase()===nome.toLowerCase())){toast('Já existe uma categoria com este nome.');return;}const oldName=item&&item.nome,target=item||{id:uid(),code:String(state.categorias.length+1).padStart(3,'0')};Object.assign(target,{nome,parentId:document.getElementById('categoryParent').value||null,pdvCode:document.getElementById('categoryPdv').value.trim(),color:document.getElementById('categoryColor').value,active:document.getElementById('categoryActive').checked});if(!item)state.categorias.push(target);state.products.forEach(p=>{if(p.categoryId===target.id||oldName&&p.category===oldName){p.categoryId=target.id;p.category=nome;}});save('categorias');save('products');closeModal();renderAll();toast('Categoria salva.');};if(item)document.getElementById('categoryDelete').onclick=()=>{if(categoryProductCount(item)||state.categorias.some(x=>x.parentId===item.id)){toast('Remova produtos e subcategorias vinculados antes de excluir.');return;}deleteCrudItem('categorias',item.id);};}
function questionTypeLabel(type){return{single:'Uma opção',multiple:'Múltiplas opções',text:'Texto livre',quantity:'Quantidade'}[type]||'Uma opção';}
function questionLinkedProductIds(item){return state.products.filter(p=>(p.questionIds||[]).includes(item&&item.id)).map(p=>p.id);}
function exportQuestionsCsv(){crudOptions.perguntas=false;downloadCsvFile('perguntas-'+todayStr()+'.csv',[['Código','Pergunta','Tipo','Obrigatória','Máximo','Situação','Respostas'],...state.perguntas.map((x,i)=>[x.code||i+1,x.texto,x.type||'single',x.required?'sim':'não',x.maxChoices||1,x.active===false?'pausada':'ativa',(x.answers||[]).map(a=>`${typeof a==='string'?a:a.text}:${Number(a&&a.price)||0}`).join('|')])]);}
function exportQuestionsPackage(){crudOptions.perguntas=false;downloadJsonFile('pacote-perguntas-'+todayStr()+'.json',{format:'cantina-perguntas',version:1,exportedAt:new Date().toISOString(),questions:state.perguntas.map(x=>({...x,productIds:questionLinkedProductIds(x)}))});}
function duplicateSelectedQuestion(){crudOptions.perguntas=false;const source=state.perguntas.find(x=>x.id===crudSelected.perguntas);if(!source){toast('Selecione uma pergunta para duplicar.');return;}const copy=JSON.parse(JSON.stringify(source));copy.id=uid();copy.code='';copy.texto=source.texto+' — Cópia';copy.sortOrder=state.perguntas.length;copy.answers=(copy.answers||[]).map(a=>typeof a==='string'?a:{...a,id:uid()});state.perguntas.push(copy);crudSelected.perguntas=copy.id;save('perguntas');renderAll();toast('Pergunta duplicada para revisão.');}
function setQuestionsStatus(active){crudOptions.perguntas=false;const ids=crudSelected.perguntas?[crudSelected.perguntas]:state.perguntas.map(x=>x.id);ids.forEach(id=>{const x=state.perguntas.find(q=>q.id===id);if(x)x.active=active;});save('perguntas');renderAll();toast(`${ids.length} pergunta(s) ${active?'ativada(s)':'pausada(s)'}.`);}
function parseImportedAnswers(value){if(Array.isArray(value))return value.map(a=>typeof a==='string'?{id:uid(),text:a,price:0}:{id:a.id||uid(),text:String(a.text||''),price:Math.max(0,Number(a.price)||0)}).filter(a=>a.text);return String(value||'').split('|').filter(Boolean).map(part=>{const pos=part.lastIndexOf(':'),price=pos>=0?Number(part.slice(pos+1).replace(',','.')):0;return{id:uid(),text:(pos>=0?part.slice(0,pos):part).trim(),price:Number.isFinite(price)?Math.max(0,price):0};}).filter(a=>a.text);}
function importQuestionsFile(format='csv'){crudOptions.perguntas=false;const input=document.createElement('input');input.type='file';input.accept=format==='json'?'.json,application/json':'.csv,text/csv';input.onchange=async()=>{const file=input.files[0];if(!file)return;try{let incoming;if(format==='json'){const data=JSON.parse(await file.text());incoming=Array.isArray(data)?data:data&&data.format==='cantina-perguntas'?data.questions:null;if(!Array.isArray(incoming))throw new Error('Pacote de perguntas inválido.');}else{const lines=(await file.text()).replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean);incoming=lines.slice(1).map(line=>{const c=line.split(';').map(v=>v.replace(/^"|"$/g,'').replace(/""/g,'"'));return{code:(c[0]||'').trim(),texto:(c[1]||'').trim(),type:(c[2]||'single').trim(),required:String(c[3]).toLowerCase()==='sim',maxChoices:Number(c[4])||1,active:String(c[5]||'ativa').toLowerCase()!=='pausada',answers:c[6]||''};}).filter(x=>x.texto);}if(!incoming.length)throw new Error('Nenhuma pergunta válida foi encontrada.');if(!confirm(`Importar ${incoming.length} pergunta(s) de ${file.name}?`))return;let added=0,updated=0;incoming.forEach(raw=>{const code=String(raw.code||'').trim(),existing=state.perguntas.find(x=>(raw.id&&x.id===raw.id)||(code&&x.code===code));const type=['single','multiple','text','quantity'].includes(raw.type)?raw.type:'single',target=existing||{id:raw.id||uid()};Object.assign(target,{code,texto:String(raw.texto||'').trim(),type,required:!!raw.required,maxChoices:type==='multiple'?Math.max(1,Number(raw.maxChoices)||1):1,active:raw.active!==false,answers:['single','multiple'].includes(type)?parseImportedAnswers(raw.answers):[],sortOrder:Number(raw.sortOrder)||state.perguntas.length});if(existing)updated++;else{state.perguntas.push(target);added++;}if(Array.isArray(raw.productIds))state.products.forEach(p=>{p.questionIds=(p.questionIds||[]).filter(id=>id!==target.id);if(raw.productIds.includes(p.id))p.questionIds.push(target.id);});});save('perguntas');save('products');renderAll();toast(`${added} pergunta(s) incluída(s) e ${updated} atualizada(s).`);}catch(error){toast(error.message||'Não foi possível importar o arquivo.');}};input.click();}
function renderQuestions(el){const list=(state.perguntas||[]).slice().sort((a,b)=>(Number(a.sortOrder)||0)-(Number(b.sortOrder)||0)),rows=list.map((item,index)=>`<tr data-search="${h(((item.texto||'')+' '+questionTypeLabel(item.type)).toLowerCase())}" class="${crudSelected.perguntas===item.id?'selected':''}" onclick="crudSelected.perguntas=${jsArg(item.id)};renderQuestions(document.getElementById('view-perguntas'))" ondblclick="openQuestionModal(${jsArg(item.id)})"><td>${h(item.code||String(index+1).padStart(3,'0'))}</td><td>${h(item.texto||'—')}</td><td>${h(questionTypeLabel(item.type))}</td><td>${(item.answers||[]).length}</td><td>${state.products.filter(p=>(p.questionIds||[]).includes(item.id)).length}</td><td>${item.required?'Sim':'Não'}</td><td><span class="tag ${item.active===false?'tag-gray':'tag-green'}">${item.active===false?'Pausada':'Ativa'}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Não há perguntas cadastradas</td></tr>';el.innerHTML=`<div class="workspace-gray"><section class="op-window question-window"><header class="op-titlebar"><span>Perguntas</span><span class="op-controls"><span onclick="closeOperationalWindow()" style="cursor:pointer" title="Fechar">×</span></span></header><div class="op-toolbar"><div class="op-search"><span>⌕</span><input id="questionSearch" placeholder="Pesquisar aqui..."></div><div class="op-toolbar-spacer"></div><div class="pdv-menu-wrap"><button class="op-btn" onclick="toggleCrudOptions('perguntas')">••• &nbsp; Opções ▾</button>${crudOptions.perguntas?`<div class="pdv-menu" style="top:48px;right:0;left:auto"><button onclick="window.print()">▣ Imprimir</button><button onclick="openCrudOrdering('perguntas')">↕ Ordenação manual</button><button onclick="renderAll()">↻ Atualizar</button></div>`:''}</div><button class="op-btn" onclick="editSelectedCrud('perguntas')" ${crudSelected.perguntas?'':'disabled'}>✎ &nbsp; Editar</button><button class="op-btn primary" onclick="openQuestionModal()">＋ &nbsp; Novo</button></div><div class="op-tabs"><button class="active">Perguntas (${list.length})</button></div><div class="op-grid"><table><thead><tr><th>Cód. Sistema</th><th>Pergunta</th><th>Tipo de Resposta</th><th>Respostas</th><th>Produtos Vinculados</th><th>Obrigatória</th><th>Status</th></tr></thead><tbody id="questionRows">${rows}</tbody></table></div><footer class="op-footer"><span>Registros: ${list.length}</span><span>Ordenação: Manual</span></footer></section></div>`;document.getElementById('questionSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#questionRows tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none');};}
const renderQuestionsBase=renderQuestions;
renderQuestions=function(el){renderQuestionsBase(el);if(!crudOptions.perguntas)return;const menu=el.querySelector('.pdv-menu');if(!menu)return;menu.style.minWidth='270px';menu.innerHTML=`<button onclick="crudOptions.perguntas=false;window.print()">▣ Imprimir</button><button onclick="openCrudOrdering('perguntas')">↕ Ordenação manual</button><button onclick="crudOptions.perguntas=false;renderAll();toast('Lista atualizada.')">↻ Atualizar</button><button onclick="duplicateSelectedQuestion()" ${crudSelected.perguntas?'':'disabled'}>▣ Duplicar selecionada</button><b>Alterar Situação</b><button onclick="setQuestionsStatus(true)">✓ Ativar ${crudSelected.perguntas?'selecionada':'todas'}</button><button onclick="setQuestionsStatus(false)">‖ Pausar ${crudSelected.perguntas?'selecionada':'todas'}</button><b>Exportar Perguntas</b><button onclick="exportQuestionsCsv()">▧ Para arquivo CSV</button><button onclick="exportQuestionsPackage()">▧ Pacote completo</button><b>Importar Perguntas</b><button onclick="importQuestionsFile('csv')">▧ De arquivo CSV</button><button onclick="importQuestionsFile('json')">▧ De pacote completo</button>`;};
function renderCrudView(elId, entityKey){
  const cfg = CRUD_CONFIGS[entityKey];
  const el = document.getElementById(elId);
  if(entityKey==='complementos'&&typesSizesMode){renderTypesSizes(el);return;}
  if(entityKey==='complementos'){renderComplements(el);return;}
  if(entityKey==='paymentMethods'){renderPaymentMethods(el);return;}
  if(entityKey==='contaCategorias'){renderAccountCategories(el);return;}
  if(entityKey==='fornecedores'){renderSuppliers(el);return;}
  if(entityKey==='observacoes'){renderObservations(el);return;}
  if(entityKey==='categorias'){renderCategories(el);return;}
  if(entityKey==='perguntas'){renderQuestions(el);return;}
  const list = (state[entityKey]||[]).slice().sort((a,b)=>(Number(a.sortOrder)||0)-(Number(b.sortOrder)||0));
  const rows = list.length ? list.map((item,idx)=>`<tr data-search="${h(cfg.fields.map(f=>item[f.key]||'').join(' ').toLowerCase())}" class="${crudSelected[entityKey]===item.id?'selected':''}" onclick="selectCrudRow(${jsArg(entityKey)},${jsArg(item.id)})" ondblclick="openCrudModal(${jsArg(entityKey)},${jsArg(item.id)})"><td class="mono">${h(item.code||String(idx+1).padStart(3,'0'))}</td>${cfg.fields.map(f=>`<td>${f.type==='number'?fmt(item[f.key]):h(item[f.key]||'—')}</td>`).join('')}${entityKey==='complementos'?`<td class="mono">${state.products.filter(p=>(p.complementIds||[]).includes(item.id)).length}</td><td>${item.active===false?'<span class="tag tag-gray">Pausado</span>':'<span class="tag tag-green">À venda</span>'}</td>`:''}<td><button class="op-mini" onclick="event.stopPropagation();openCrudModal(${jsArg(entityKey)},${jsArg(item.id)})">Editar</button><button class="op-mini" onclick="event.stopPropagation();deleteCrudItem(${jsArg(entityKey)},${jsArg(item.id)})">Excluir</button></td></tr>`).join('') : `<tr><td colspan="${cfg.fields.length+(entityKey==='complementos'?4:2)}" class="empty">Não há registros para mostrar</td></tr>`;
  const simple=entityKey==='observacoes'||entityKey==='categorias'||entityKey==='perguntas';
  el.innerHTML = `<div class="workspace-gray"><section class="op-window"><header class="op-titlebar"><span>${cfg.title}</span><span class="op-controls"><span onclick="closeOperationalWindow()" style="cursor:pointer" title="Fechar">×</span></span></header>${simple?`<div style="padding:14px 18px 0;color:var(--c-text-3);font-size:13px">${h(cfg.sub)}</div>`:''}<div class="op-toolbar"><div class="op-search"><input id="crudSearch_${entityKey}" placeholder="Pesquisar aqui..."></div><div class="op-toolbar-spacer"></div><div class="pdv-menu-wrap"><button class="op-btn" onclick="toggleCrudOptions(${jsArg(entityKey)})">••• &nbsp; Opções ▾</button>${crudOptions[entityKey]?`<div class="pdv-menu" style="top:48px"><button onclick="window.print()">▣ &nbsp; Imprimir</button><button onclick="toast('A ordenação manual usa a sequência atual da lista.')">↕ &nbsp; Ordenação manual</button><button onclick="renderAll();toast('Lista atualizada.')">↻ &nbsp; Atualizar</button></div>`:''}</div><button class="op-btn" onclick="editSelectedCrud(${jsArg(entityKey)})" ${crudSelected[entityKey]?'':'disabled'}><span class="op-ico">✎</span> Editar</button><button class="op-btn primary" onclick="openCrudModal(${jsArg(entityKey)})"><span class="op-ico">＋</span> Novo</button></div><div class="op-grid"><table><thead><tr><th>Cód. Sistema</th>${cfg.fields.map(f=>`<th>${f.label}</th>`).join('')}${entityKey==='complementos'?'<th>Produtos Vinculados</th><th>Status Venda</th>':''}<th>Ações</th></tr></thead><tbody id="crudRows_${entityKey}">${rows}</tbody></table></div><footer class="op-footer"><span>Registros: ${list.length}</span><span>Ordenação: Manual</span></footer></section></div>`;
  document.getElementById('crudSearch_'+entityKey).oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#crudRows_'+entityKey+' tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none');};
}
function renderSuppliersLegacy(el){
  const list=state.fornecedores||[];const rows=list.length?list.map((f,i)=>`<tr data-search="${h(Object.values(f).join(' ').toLowerCase())}" onclick="crudSelected.fornecedores=${jsArg(f.id)};renderSuppliers(document.getElementById('view-fornecedores'))" class="${crudSelected.fornecedores===f.id?'selected':''}"><td>${h(f.nome||'—')}</td><td>${h(f.razaoSocial||'—')}</td><td>${h(f.telefone||'—')}</td><td>${h(f.documento||'—')}</td><td>${h(f.email||'—')}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Nenhum fornecedor cadastrado.</td></tr>';
  el.innerHTML=`<div class="workspace-gray"><section class="op-window"><header class="op-titlebar"><span>Fornecedores</span><span class="op-controls"><button onclick="closeOperationalWindow()">×</button></span></header><div class="op-toolbar"><div class="op-search"><input id="supplierSearch" placeholder="Pesquisar aqui..."></div><div class="op-toolbar-spacer"></div><button class="op-btn" onclick="window.print()">••• &nbsp; Opções</button><button class="op-btn" onclick="editSelectedCrud('fornecedores')" ${crudSelected.fornecedores?'':'disabled'}>✎ &nbsp; Editar</button><button class="op-btn primary" onclick="openCrudModal('fornecedores')">＋ &nbsp; Novo</button></div><div class="op-grid"><table><thead><tr><th>Nome</th><th>Razão Social</th><th>Tel. Principal</th><th>CNPJ ou CPF</th><th>E-mail</th></tr></thead><tbody id="supplierRows">${rows}</tbody></table></div><footer class="op-footer"><span>Registros: ${list.length}</span><span></span></footer></section></div>`;document.getElementById('supplierSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#supplierRows tr[data-search]').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none');};
}
function renderAccountCategoriesLegacy(el){
  const defaults=['Administrativo - Geral','Aquisição de Bens e Equipamentos','Despesas e Utilidades Prediais','Empréstimos','Fornecedores','Impostos, Taxas e Tarifas','Salários, Encargos e Benefícios'];const list=state.contaCategorias||[];const shown=list.length?list:defaults.map((nome,i)=>({id:'default-'+i,nome,system:true}));const rows=shown.map(c=>`<tr onclick="${c.system?"toast('Categoria padrão; crie uma categoria própria para personalizar.')":`crudSelected.contaCategorias=${jsArg(c.id)};renderAccountCategories(document.getElementById('view-contascategorias'))`}" class="${crudSelected.contaCategorias===c.id?'selected':''}"><td>▸ ${h(c.nome)}</td><td>${h(c.grupoDre||'—')}</td><td>${c.system?'Padrão':'Personalizada'}</td></tr>`).join('');
  el.innerHTML=`<div class="workspace-gray"><section class="op-window" style="max-width:850px"><header class="op-titlebar"><span>Categoria de Contas</span><span class="op-controls"><button onclick="closeOperationalWindow()">×</button></span></header><div style="padding:12px 18px;color:var(--c-text-3)">Definir um Grupo DRE na categoria principal atualiza automaticamente as subcategorias.</div><div class="op-toolbar"><div class="op-toolbar-spacer"></div><button class="op-btn" onclick="editSelectedCrud('contaCategorias')" ${crudSelected.contaCategorias?'':'disabled'}>✎ &nbsp; Editar</button><button class="op-btn primary" onclick="openCrudModal('contaCategorias')">＋ &nbsp; Novo</button></div><div class="op-grid"><table><thead><tr><th>Categoria</th><th>Grupo DRE</th><th>Origem</th></tr></thead><tbody>${rows}</tbody></table></div><footer class="op-footer"><span>Registros: ${shown.length}</span><span></span></footer></section></div>`;
}
function renderPaymentMethodsLegacy(el){
  const fixed=[{nome:'Dinheiro',tipo:'Dinheiro'},{nome:'Cartão de Crédito',tipo:'Cartão'},{nome:'Cartão de Débito',tipo:'Cartão'},{nome:'Pix',tipo:'Pix'},{nome:'Fiado',tipo:'Conta Corrente'}];const list=[...fixed,...(state.paymentMethods||[])];const selected=list.find(x=>x.id===crudSelected.paymentMethods)||list[0];const rows=list.map((p,i)=>`<tr class="${selected===p?'selected':''}" onclick="crudSelected.paymentMethods=${jsArg(p.id||'')};renderPaymentMethods(document.getElementById('view-pagamentos'))"><td>${h(p.nome)}</td><td>${h(p.tipo||'Outros')}</td><td>${Number(p.diasReceber)||0}</td><td>${Number(p.taxa||0).toFixed(2)}%</td></tr>`).join('');const brands=['Visa','Mastercard','American Express','Elo','Hipercard'];
  el.innerHTML=`<div class="workspace-gray"><section class="op-window"><header class="op-titlebar"><span>Formas de Pagamento</span><span class="op-controls"><button onclick="closeOperationalWindow()">×</button></span></header><div class="op-toolbar"><div class="op-toolbar-spacer"></div><button class="op-btn" onclick="editSelectedCrud('paymentMethods')" ${selected&&selected.id?'':'disabled'}>✎ &nbsp; Editar</button><button class="op-btn primary" onclick="openCrudModal('paymentMethods')">＋ &nbsp; Nova Forma de Pagamento</button><button class="op-btn" onclick="openCardBrandModal()">＋ &nbsp; Nova Bandeira</button></div><div style="display:grid;grid-template-columns:45% 55%;min-height:500px"><div><div class="op-tabs"><button class="active">Formas de Pagamento</button></div><div class="op-grid"><table><thead><tr><th>Forma</th><th>Tipo</th><th>Dias p/ Receber</th><th>Taxa</th></tr></thead><tbody>${rows}</tbody></table></div></div><div><div class="op-tabs"><button class="active">Bandeiras de Cartões</button></div><div class="op-grid"><table><thead><tr><th>Vincular</th><th>Bandeiras para Vincular</th><th>Dias p/ Receber</th><th>Taxa</th></tr></thead><tbody>${brands.map(b=>`<tr><td><input type="checkbox"></td><td>${b}</td><td><input type="number" value="30" style="width:70px"></td><td><input type="number" value="0" step="0.01" style="width:70px"></td></tr>`).join('')}</tbody></table></div></div></div><footer class="op-footer"><span>Formas=${list.length}</span><span>Bandeiras=${brands.length}</span></footer></section></div>`;
}
function openCardBrandModal(id){const item=id?state.cardBrands.find(x=>x.id===id):null;const fiscal=[['01','Visa'],['02','Mastercard'],['03','American Express'],['04','Sorocred'],['05','Diners Club'],['06','Elo'],['07','Hipercard'],['08','Aura'],['09','Cabal'],['99','Outros']];openModal('Bandeiras de Cartões',`<div class="consumer-form-frame brand-form-frame"><div class="field"><label>Descrição:</label><input id="brandDescription" value="${h(item&&item.nome||'')}" autofocus></div><div class="field"><label>Identificação Fiscal:</label><select id="brandFiscal"><option value=""></option>${fiscal.map(([code,name])=>`<option value="${code}" ${item&&item.identificacaoFiscal===code?'selected':''}>${code} - ${name}</option>`).join('')}</select></div></div><div class="consumer-modal-actions brand-actions"><button class="consumer-delete" id="brandDelete" ${item?'':'disabled'}>✕ &nbsp; Excluir</button><span></span><button class="consumer-back" onclick="closeModal()">〈 &nbsp; Voltar</button><button class="consumer-save" id="brandSave">✓ &nbsp; Salvar</button></div>`);const modal=document.querySelector('#modalRoot .modal');modal.classList.add('finance-record-modal','brand-record-modal');document.getElementById('brandSave').onclick=()=>{const nome=document.getElementById('brandDescription').value.trim(),identificacaoFiscal=document.getElementById('brandFiscal').value;if(!nome){toast('Informe a descrição.');return;}if(!identificacaoFiscal){toast('Selecione a identificação fiscal.');return;}if(item)Object.assign(item,{nome,identificacaoFiscal});else state.cardBrands.push({id:uid(),nome,identificacaoFiscal});save('cardBrands');closeModal();renderAll();toast('Bandeira salva.');};if(item)document.getElementById('brandDelete').onclick=()=>{if(!confirm('Excluir esta bandeira?'))return;state.cardBrands=state.cardBrands.filter(x=>x.id!==item.id);save('cardBrands');closeModal();renderAll();toast('Bandeira excluída.');};}
function openCrudModal(entityKey, id){
  if(entityKey==='paymentMethods'){openPaymentMethodModal(id);return;}
  if(entityKey==='contaCategorias'){openAccountCategoryModal(id);return;}
  if(entityKey==='fornecedores'){openSupplierModal(id);return;}
  if(entityKey==='perguntas'){openQuestionModal(id);return;}
  if(entityKey==='observacoes'){openObservationModal(id);return;}
  if(entityKey==='categorias'){openCategoryModal(id);return;}
  const cfg = CRUD_CONFIGS[entityKey];
  const item = id ? state[entityKey].find(x=>x.id===id) : null;
  // Janela pequena (22/10, pedido do dono): era .record-modal, feita para cadastro grande — 1020 px de
  // largura para um campo só, campo e botão colados na borda e "Salvar" da largura toda.
  openModal((item?'Editar':'Novo')+' — '+cfg.title, `
    <div class="crud-modal-body">${cfg.fields.map(f=>`<div class="field"><label>${h(f.label)}</label><input id="crud_${f.key}" type="${f.type==='number'?'number':'text'}" ${f.type==='number'?'step="0.01"':''} value="${h(item?(item[f.key]??''):'')}"></div>`).join('')}</div>
    <div class="crud-modal-actions"><button class="btn" onclick="closeModal()">Cancelar</button><button class="btn btn-primary" id="crudSaveBtn">Salvar</button></div>`);
  document.querySelector('#modalRoot .modal').classList.add('crud-modal');
  document.querySelectorAll('#modalRoot .crud-modal-body input').forEach(i=>i.addEventListener('keydown',e=>{ if(e.key==='Enter') document.getElementById('crudSaveBtn').click(); }));
  document.querySelector('#modalRoot .crud-modal-body input')?.focus();
  document.getElementById('crudSaveBtn').onclick = ()=>{
    const data = {};
    for(const f of cfg.fields){
      const v = document.getElementById('crud_'+f.key).value;
      data[f.key] = f.type==='number' ? (parseFloat(v)||0) : v.trim();
    }
    if(!data[cfg.fields[0].key]){ toast('Preencha o campo '+cfg.fields[0].label+'.'); return; }
    if(item){ Object.assign(item,data); } else { state[entityKey].push({id:uid(), ...data}); }
    save(entityKey); closeModal(); renderAll(); toast('Salvo com sucesso.'); logAction(cfg.title+' — registro salvo');
  };
}
function openQuestionModal(id){const item=id?state.perguntas.find(x=>x.id===id):null,answers=Array.isArray(item&&item.answers)?item.answers:[];openModal(item?'Editar Pergunta':'Nova Pergunta',`<div class="record-body"><div class="record-tabs"><button class="active">Principal</button><button>Respostas</button></div><div class="consumer-form-frame"><div class="field"><label>Pergunta</label><input id="questionText" value="${h(item&&item.texto||'')}"></div><div class="row"><div class="field"><label>Tipo da resposta</label><select id="questionType" onchange="toggleQuestionAnswers()">${[['single','Uma opção'],['multiple','Múltiplas opções'],['text','Texto livre'],['quantity','Quantidade']].map(([v,n])=>`<option value="${v}" ${item&&item.type===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label>Quantidade máxima de escolhas</label><input id="questionMax" type="number" min="1" value="${Number(item&&item.maxChoices)||1}"></div></div><label><input id="questionRequired" type="checkbox" ${item&&item.required?'checked':''}> Resposta obrigatória</label><label style="margin-left:18px"><input id="questionActive" type="checkbox" ${!item||item.active!==false?'checked':''}> Ativa</label><div id="questionAnswersBox" style="margin-top:15px"><div style="display:flex;justify-content:space-between"><b>Opções de resposta</b><button class="op-btn" onclick="addQuestionAnswer()">＋ Adicionar</button></div><div id="questionAnswerRows"></div></div></div><div class="consumer-modal-actions"><button onclick="closeModal()">Voltar</button><button class="consumer-save" onclick="saveQuestion(${jsArg(id||'')})">✓ Salvar</button></div></div>`,true);document.querySelector('#modalRoot .modal').classList.add('record-modal');window.questionAnswersDraft=answers.map(x=>typeof x==='string'?{id:uid(),text:x,price:0}:({...x}));renderQuestionAnswers();toggleQuestionAnswers();}
function toggleQuestionAnswers(){const type=document.getElementById('questionType')?.value,box=document.getElementById('questionAnswersBox'),max=document.getElementById('questionMax');if(box)box.hidden=type==='text'||type==='quantity';if(max)max.disabled=type!=='multiple';}
function addQuestionAnswer(){window.questionAnswersDraft.push({id:uid(),text:'',price:0});renderQuestionAnswers();}
function renderQuestionAnswers(){const el=document.getElementById('questionAnswerRows');if(!el)return;el.innerHTML=window.questionAnswersDraft.map((a,i)=>`<div class="row" style="align-items:end"><div class="field"><label>Resposta</label><input value="${h(a.text)}" oninput="questionAnswersDraft[${i}].text=this.value"></div><div class="field" style="max-width:150px"><label>Adicional</label><input type="number" step="0.01" value="${Number(a.price)||0}" oninput="questionAnswersDraft[${i}].price=Number(this.value)||0"></div><button class="op-mini" onclick="questionAnswersDraft.splice(${i},1);renderQuestionAnswers()">✕</button></div>`).join('')||'<p class="empty">Nenhuma opção cadastrada.</p>';}
function saveQuestion(id){const texto=document.getElementById('questionText').value.trim(),type=document.getElementById('questionType').value,answers=window.questionAnswersDraft.filter(x=>x.text.trim()).map(x=>({...x,text:x.text.trim()}));if(!texto){toast('Informe a pergunta.');return;}if(['single','multiple'].includes(type)&&!answers.length){toast('Adicione ao menos uma opção de resposta.');return;}const data={texto,type,answers,required:document.getElementById('questionRequired').checked,active:document.getElementById('questionActive').checked,maxChoices:type==='multiple'?Math.max(1,parseInt(document.getElementById('questionMax').value,10)||1):1},item=state.perguntas.find(x=>x.id===id);if(item)Object.assign(item,data);else state.perguntas.push({id:uid(),...data});save('perguntas');closeModal();renderAll();toast('Pergunta salva.');}
function openAccountCategoryModal(id){const item=id?state.contaCategorias.find(x=>x.id===id):null;const parents=state.contaCategorias.filter(x=>x.id!==id&&(x.isPrincipal||!x.parentId));const dreGroups=['Receita Bruta','Deduções da Receita','Custos Variáveis','Despesas Operacionais','Despesas Administrativas','Despesas Financeiras','Investimentos','Outras Receitas e Despesas'];openModal('Categoria de Conta',`<div class="consumer-form-frame account-category-frame"><div class="field"><label>Descrição:</label><input id="accountCategoryDescription" value="${h(item&&item.nome||'')}" autofocus></div><label class="account-category-check"><input id="accountCategoryPrincipal" type="checkbox" ${item&&item.isPrincipal?'checked':''} onchange="toggleAccountCategoryParent()"> Salvar como categoria principal</label><div class="field"><label>Subcategoria de:</label><select id="accountCategoryParent"><option value=""></option>${parents.map(p=>`<option value="${p.id}" ${item&&item.parentId===p.id?'selected':''}>${h(p.nome)}</option>`).join('')}</select></div><div class="field"><label>Grupo DRE:</label><select id="accountCategoryDre"><option value=""></option>${dreGroups.map(g=>`<option ${item&&item.grupoDre===g?'selected':''}>${g}</option>`).join('')}</select></div></div><div class="consumer-modal-actions"><button class="consumer-back" onclick="closeModal()">〈 &nbsp; Voltar</button><button class="consumer-save" id="accountCategorySave">✓ &nbsp; Salvar</button></div>`);document.querySelector('#modalRoot .modal').classList.add('finance-record-modal','account-category-modal');toggleAccountCategoryParent();document.getElementById('accountCategorySave').onclick=()=>{const nome=document.getElementById('accountCategoryDescription').value.trim(),isPrincipal=document.getElementById('accountCategoryPrincipal').checked,parentId=document.getElementById('accountCategoryParent').value||null,grupoDre=document.getElementById('accountCategoryDre').value;if(!nome){toast('Informe a descrição.');return;}if(!isPrincipal&&!parentId){toast('Escolha a categoria principal ou marque como categoria principal.');return;}const data={nome,isPrincipal,parentId:isPrincipal?null:parentId,grupoDre};if(item)Object.assign(item,data);else state.contaCategorias.push({id:uid(),...data});save('contaCategorias');closeModal();renderAll();toast('Categoria de conta salva.');};}
function toggleAccountCategoryParent(){const principal=document.getElementById('accountCategoryPrincipal'),parent=document.getElementById('accountCategoryParent');if(!principal||!parent)return;parent.disabled=principal.checked;if(principal.checked)parent.value='';}
function openSupplierModal(id){const item=id?state.fornecedores.find(x=>x.id===id):null;const states=['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];openModal(item?'Editar Fornecedor':'Novo Fornecedor',`<div class="supplier-record"><div class="record-tabs"><button class="active">Geral</button></div><div class="supplier-form"><div class="field span2"><label>Nome Fantasia</label><input id="supplierNome" value="${h(item&&item.nome||'')}" autofocus></div><div class="field span2"><label>Razão Social</label><input id="supplierRazao" value="${h(item&&item.razaoSocial||'')}"></div><div class="field"><label>CNPJ ou CPF</label><input id="supplierDocumento" value="${h(item&&item.documento||'')}"></div><div class="field"><label>RG ou IE</label><input id="supplierRgIe" value="${h(item&&item.rgIe||'')}"></div><div class="field"><label>Telefone Principal</label><input id="supplierTelefone" value="${h(item&&item.telefone||'')}"></div><div class="field"><label>Telefone Secundário</label><input id="supplierTelefone2" value="${h(item&&item.telefoneSecundario||'')}"></div><div class="field span2"><label>E-mail</label><input id="supplierEmail" type="email" value="${h(item&&item.email||'')}"></div><h3 class="supplier-address-title span2">Endereço</h3><div class="supplier-address span2"><div class="field cep"><label>CEP</label><div class="cep-control"><input id="supplierCep" value="${h(item&&item.cep||'')}"><button type="button" onclick="lookupSupplierCep()">⌕ &nbsp; Buscar</button></div></div><div class="field"><label>Endereço</label><input id="supplierEndereco" value="${h(item&&item.endereco||'')}"></div><div class="field number"><label>Número</label><input id="supplierNumero" value="${h(item&&item.numero||'')}"></div><div class="field"><label>Complemento</label><input id="supplierComplemento" value="${h(item&&item.complemento||'')}"></div><div class="field"><label>Bairro</label><input id="supplierBairro" value="${h(item&&item.bairro||'')}"></div></div><div class="field city"><label>Cidade</label><input id="supplierCidade" value="${h(item&&item.cidade||'São Paulo')}"></div><div class="field"><label>UF</label><select id="supplierUf"><option value=""></option>${states.map(uf=>`<option ${item&&item.uf===uf||(!item&&uf==='SP')?'selected':''}>${uf}</option>`).join('')}</select></div></div><div class="consumer-modal-actions"><button class="consumer-back" onclick="closeModal()">〈 &nbsp; Voltar</button><button class="consumer-save" id="supplierSave">✓ &nbsp; Salvar</button></div></div>`);const modal=document.querySelector('#modalRoot .modal');modal.classList.add('finance-record-modal','supplier-record-modal');document.getElementById('supplierSave').onclick=()=>{const nome=document.getElementById('supplierNome').value.trim();if(!nome){toast('Informe o Nome Fantasia.');return;}const data={nome,razaoSocial:document.getElementById('supplierRazao').value.trim(),documento:document.getElementById('supplierDocumento').value.trim(),rgIe:document.getElementById('supplierRgIe').value.trim(),telefone:document.getElementById('supplierTelefone').value.trim(),telefoneSecundario:document.getElementById('supplierTelefone2').value.trim(),email:document.getElementById('supplierEmail').value.trim(),cep:document.getElementById('supplierCep').value.trim(),endereco:document.getElementById('supplierEndereco').value.trim(),numero:document.getElementById('supplierNumero').value.trim(),complemento:document.getElementById('supplierComplemento').value.trim(),bairro:document.getElementById('supplierBairro').value.trim(),cidade:document.getElementById('supplierCidade').value.trim(),uf:document.getElementById('supplierUf').value};if(item)Object.assign(item,data);else state.fornecedores.push({id:uid(),...data});save('fornecedores');closeModal();renderAll();toast('Fornecedor salvo.');};}
function lookupSupplierCep(){const cep=document.getElementById('supplierCep').value.replace(/\D/g,'');if(cep.length!==8){toast('Informe um CEP com 8 dígitos.');return;}toast('Busca externa de CEP requer conexão; preencha o endereço ou configure um provedor.');}
function openPaymentMethodModal(id){
  const item=id?state.paymentMethods.find(x=>x.id===id):null;
  const types=['Vale Presente','Vale Combustível','Depósito Bancário','Pix','Transferência bancária, Carteira Digital','Programa de fidelidade, Cashback, Crédito Virtual','Outros'];
  const acquirers=[['03106213000190','Administradora de Cartões Sicredi Ltda.'],['03106213000271','Administradora de Cartões Sicredi Ltda. (filial RS)'],['60419645000195','Banco American Express S/A - AMEX'],['62421979000129','Banco CIFRA S/A'],['58160789000128','BANCO SAFRA S/A'],['07679404000100','BANCO TOPÁZIO S/A'],['01027058000191','Cielo S.A.'],['01425787000104','Redecard S.A.'],['10573521000191','Stone Instituição de Pagamento S.A.'],['08561701000101','PagSeguro Internet Instituição de Pagamento S.A.']];
  window.paymentAcquirerDraft=item&&item.credenciadoraCnpj?{cnpj:item.credenciadoraCnpj,empresa:item.credenciadora}:null;
  openModal('Formas de Pagamento',`<div class="consumer-form-frame"><div class="field"><label>Descrição:</label><input id="pmDescription" value="${h(item&&item.nome||'')}" autofocus></div><div class="field"><label>Tipo:</label><select id="pmType">${types.map(t=>`<option ${item&&item.tipo===t?'selected':''}>${h(t)}</option>`).join('')}</select></div><div class="field acquirer-field"><label>Credenciadora do Cartão ou Pix / Adquirente:</label><button type="button" id="pmAcquirerButton" class="acquirer-select" onclick="toggleAcquirerPicker()"><span id="pmAcquirerLabel">${h(item&&item.credenciadoraCnpj?item.credenciadoraCnpj+' — '+item.credenciadora:'')}</span><span>▾</span></button><div id="pmAcquirerPicker" class="acquirer-picker" hidden><input id="pmAcquirerSearch" placeholder="Pesquisar CNPJ ou empresa..." oninput="filterAcquirers(this.value)"><table><thead><tr><th>CNPJ</th><th>Empresa</th></tr></thead><tbody id="pmAcquirerRows">${acquirers.map(([cnpj,empresa])=>`<tr data-search="${h((cnpj+' '+empresa).toLowerCase())}" onclick="selectPaymentAcquirer(${jsArg(cnpj)},${h(JSON.stringify(empresa))})"><td>${cnpj}</td><td>${h(empresa)}</td></tr>`).join('')}</tbody></table></div></div></div><div class="consumer-modal-actions"><button class="consumer-back" onclick="closeModal()">〈 &nbsp; Voltar</button><button class="consumer-save" id="pmSave">✓ &nbsp; Salvar</button></div>`);
  const modal=document.querySelector('#modalRoot .modal');modal.classList.add('finance-record-modal');
  document.getElementById('pmSave').onclick=()=>{const nome=document.getElementById('pmDescription').value.trim();if(!nome){toast('Informe a descrição.');return;}const chosen=window.paymentAcquirerDraft||{};const data={nome,tipo:document.getElementById('pmType').value,credenciadora:chosen.empresa||'',credenciadoraCnpj:chosen.cnpj||''};if(item)Object.assign(item,data);else state.paymentMethods.push({id:uid(),...data});save('paymentMethods');closeModal();renderAll();toast('Forma de pagamento salva.');};
}
function toggleAcquirerPicker(){const picker=document.getElementById('pmAcquirerPicker');if(!picker)return;picker.hidden=!picker.hidden;if(!picker.hidden)document.getElementById('pmAcquirerSearch').focus();}
function filterAcquirers(value){const q=value.toLowerCase();document.querySelectorAll('#pmAcquirerRows tr').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none');}
function selectPaymentAcquirer(cnpj,empresa){window.paymentAcquirerDraft={cnpj,empresa};document.getElementById('pmAcquirerLabel').textContent=cnpj+' — '+empresa;document.getElementById('pmAcquirerPicker').hidden=true;}
function deleteCrudItem(entityKey, id){
  if(!confirm('Excluir este registro?')) return;
  state[entityKey] = state[entityKey].filter(x=>x.id!==id);
  if(entityKey==='paymentMethods'&&state.settings.paymentBrandLinks){delete state.settings.paymentBrandLinks[id];save('settings');if(selectedPaymentMethodId===id)selectedPaymentMethodId=null;}
  if(entityKey==='complementos'){state.products.forEach(p=>{p.complementIds=(p.complementIds||[]).filter(x=>x!==id);p.sizeIds=(p.sizeIds||[]).filter(x=>x!==id);});save('products');}
  if(entityKey==='perguntas'){state.products.forEach(p=>p.questionIds=(p.questionIds||[]).filter(x=>x!==id));save('products');}
  if(entityKey==='observacoes'){state.products.forEach(p=>p.observationIds=(p.observationIds||[]).filter(x=>x!==id));save('products');}
  save(entityKey); renderAll();
}

